def calc(expr: str) -> int | str:
    # Tokenize into integers and single-char operators/parens
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i].isspace():
            i += 1
        elif expr[i].isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            tokens.append(int(expr[i:j]))
            i = j
        else:
            tokens.append(expr[i])
            i += 1

    pos = [0]

    class ErrorSignal(Exception):
        pass

    def peek():
        return tokens[pos[0]] if pos[0] < len(tokens) else None

    def consume():
        t = tokens[pos[0]]
        pos[0] += 1
        return t

    def trunc_div(a, b):
        if b == 0:
            raise ErrorSignal
        q, r = divmod(a, b)
        # Python's divmod floors; adjust to truncate toward zero
        if r and (a < 0) != (b < 0):
            q += 1
        return q

    def parse_expr():
        return parse_add()

    def parse_add():
        left = parse_mul()
        while peek() in ('+', '-'):
            op = consume()
            right = parse_mul()
            left = left + right if op == '+' else left - right
        return left

    def parse_mul():
        left = parse_unary()
        while peek() in ('*', '/', '%'):
            op = consume()
            right = parse_unary()
            if op == '*':
                left *= right
            elif op == '/':
                left = trunc_div(left, right)
            else:
                left = left - right * trunc_div(left, right)
        return left

    def parse_unary():
        if peek() == '-':
            consume()
            return -parse_unary()
        return parse_power()

    def parse_power():
        base = parse_atom()
        if peek() == '^':
            consume()
            exp = parse_unary()  # right-associative + allows unary minus
            if exp < 0:
                raise ErrorSignal
            return base ** exp
        return base

    def parse_atom():
        if peek() == '(':
            consume()
            val = parse_expr()
            consume()  # ')'
            return val
        return consume()  # integer literal

    try:
        return parse_expr()
    except ErrorSignal:
        return "error"
